import{_ as t,a as r,o,a2 as a}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/introduction.md","filePath":"getting-started/introduction.md","lastUpdated":1786527783000}'),n={name:"getting-started/introduction.md"};function s(i,e,l,d,u,c){return o(),r("div",null,e[0]||(e[0]=[a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><a href="https://bagisto.com/en/" target="_blank" rel="noreferrer">Bagisto</a> is a free and open-source eCommerce platform that lets businesses launch and run modern online stores with ease. Released under the MIT license, it is fully customizable, so every part of the storefront and the admin experience can be adapted to the needs of your business.</p><p>The platform is built on top of the reliable <a href="https://laravel.com/" target="_blank" rel="noreferrer">Laravel</a> framework and uses <a href="https://vuejs.org/" target="_blank" rel="noreferrer">Vue.js</a> and <a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a> on the front end. Together they provide a clean, responsive admin interface and a smooth shopping experience for your customers.</p><p>From a single dashboard, you can manage your catalog, inventory, customers, orders, shipments, and marketing campaigns, while keeping full control over how your store looks and behaves.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Product Catalog</strong> – Simple, configurable, virtual, grouped, downloadable, bundle, and booking products, organized with categories, attributes, and attribute families.</li><li><strong>Inventory Management</strong> – Multiple inventory sources with stock tracking across warehouses and store locations.</li><li><strong>Order Management</strong> – End-to-end order processing, including invoices, shipments, refunds, and cancellations.</li><li><strong>Customer Management</strong> – Customer accounts, groups, addresses, and product reviews.</li><li><strong>Multi Channel &amp; Multi Store</strong> – Run several stores or brands from one installation, each with its own theme, catalog, and settings.</li><li><strong>Multi Currency &amp; Multi Locale</strong> – Sell worldwide with built-in currency and exchange rate handling, translations for 22 locales, and full right-to-left (RTL) support.</li><li><strong>Payment &amp; Shipping Methods</strong> – Built-in payment and shipping options that can be extended with your own integrations.</li><li><strong>Marketing Tools</strong> – Cart price rules, catalog price rules, coupons, email campaigns, and abandoned cart recovery.</li><li><strong>CMS Pages</strong> – Create and manage static content pages for your storefront.</li><li><strong>Access Control</strong> – Admin users, roles, and granular permissions for your team.</li><li><strong>Reporting</strong> – Sales, customer, product, and visitor reports to track how your store is performing.</li></ul><p>Whether you are starting a small store or scaling a large catalog across multiple markets, Bagisto gives you the tools to build and grow your online business.</p>',7)]))}const h=t(n,[["render",s]]);export{p as __pageData,h as default};
